async function updateGeminiKeyVisibility(){const e=document.getElementById("model-select");const i=document.getElementById("gemini-api-key-section");const n=document.getElementById("main");const t=document.getElementById("signout-gemini");const o=document.getElementById("modifier-dropdown");if(!e||!i||!n||!t)return;const d=e.value;const c=!!window.MODELS[d]?.url;const s=await getGeminiApiKey();const m=c&&!s;i.classList.toggle("hidden",!m);n.classList.toggle("hidden",m);t.classList.toggle("hidden",!s);if(c){if(o){o.classList.add("hidden")}}else{if(o){o.classList.remove("hidden")}}}
window.updateGeminiKeyVisibility = updateGeminiKeyVisibility;async function submitGeminiAuth(){const e=document.getElementById("gemini-api-key-input").value;if(e){await setGeminiApiKey(e);await updateGeminiKeyVisibility();document.getElementById("gemini-api-key-input").value=""}}async function cancelGeminiAuth(e){e?.preventDefault();document.getElementById("gemini-api-key-input").value="";const i=document.getElementById("model-select");const n=i.querySelectorAll("sp-menu-item");for(const t of n){if(!window.MODELS?.[t.value]?.url){t.selected=true;i.value=t.value;i.dispatchEvent(new Event("change"));break}}await updateGeminiKeyVisibility()}async function signoutGemini(e){e?.preventDefault();await removeGeminiApiKey();await updateGeminiKeyVisibility()}
